    text: FormattedText
    media: PollMedia | None = None
    voter_count: int = 0
    vote_percentage: int = 0
    recent_voter_ids: list[MessageSender] = []
    is_chosen: bool = False
    is_being_chosen: bool = False
    author: MessageSender | None = None
    addition_date: int = 0


