class SuggestedPostPriceGram(TDObject, tag="suggestedPostPriceGram", kw_only=True):
    """Describes price of a suggested post in TON Grams

    Attributes:
        gram_cent_count: The amount of 1/100 of Gram expected to be paid for the post;
            getOption("suggested_post_gram_cent_count_min")-getOption("suggested_post_gram_cent_count_max")
    """

    gram_cent_count: int = 0


class SuggestedPostStatePending(TDObject, tag="suggestedPostStatePending", kw_only=True):
    """The post must be approved or declined"""


class SuggestedPostStateApproved(TDObject, tag="suggestedPostStateApproved", kw_only=True):
    """The post was approved"""


class SuggestedPostStateDeclined(TDObject, tag="suggestedPostStateDeclined", kw_only=True):
    """The post was declined"""


class SuggestedPostInfo(TDObject, tag="suggestedPostInfo", kw_only=True):
    """Contains information about a suggested post. If the post can be approved or declined,
    then changes to the post can be also suggested. Use sendMessage with reply to the
    message and suggested post information to suggest message changes. Use addOffer to
    suggest price or time changes

    Attributes:
        price: Price of the suggested post; may be null if the post is non-paid
        send_date: Point in time (Unix timestamp) when the post is expected to be published;
            0 if the specific date isn't set yet
        state: State of the post
        can_be_approved: True, if the suggested post can be approved by the current user
            using approveSuggestedPost; updates aren't sent when value of this field changes
        can_be_declined: True, if the suggested post can be declined by the current user
            using declineSuggestedPost; updates aren't sent when value of this field changes
    """

    price: SuggestedPostPrice | None = None
    send_date: int = 0
    state: SuggestedPostState
    can_be_approved: bool = False
    can_be_declined: bool = False


class InputSuggestedPostInfo(TDObject, tag="inputSuggestedPostInfo", kw_only=True):
    """Contains information about a post to suggest

    Attributes:
        price: Price of the suggested post; pass null to suggest a post without payment. If
            the current user isn't an administrator of the channel direct messages chat and
            doesn't have enough funds to pay for the post, then the error "BALANCE_TOO_LOW"
            will be returned immediately
        send_date: Point in time (Unix timestamp) when the post is expected to be published;
            pass 0 if the date isn't restricted. If specified, then the date must be
            getOption("suggested_post_send_delay_min")-getOption("suggested_post_send_delay_max")
            seconds in the future
    """

    price: SuggestedPostPrice | None = None
    send_date: int = 0


class SuggestedPostRefundReasonPostDeleted(
    TDObject, tag="suggestedPostRefundReasonPostDeleted", kw_only=True
):
    """The post was refunded, because it was deleted by channel administrators in less than
    getOption("suggested_post_lifetime_min") seconds
    """


class SuggestedPostRefundReasonPaymentRefunded(
    TDObject, tag="suggestedPostRefundReasonPaymentRefunded", kw_only=True
):
    """The post was refunded, because the payment for the post was refunded"""


class StarAmount(TDObject, tag="starAmount", kw_only=True):
    """Describes a possibly non-integer Telegram Star amount

    Attributes:
        star_count: The integer Telegram Star amount rounded to 0
        nanostar_count: The number of 1/1000000000 shares of Telegram Stars; from -999999999
            to 999999999
    """

    star_count: int = 0
    nanostar_count: int = 0


class StarSubscriptionTypeChannel(TDObject, tag="starSubscriptionTypeChannel", kw_only=True):
    """Describes a subscription to a channel chat

    Attributes:
        can_reuse: True, if the subscription is active and the user can use the method
            reuseStarSubscription to join the subscribed chat again
        invite_link: The invite link that can be used to renew the subscription if it has
            expired; may be empty if the link isn't available anymore
    """

    can_reuse: bool = False
    invite_link: str = ""


class StarSubscriptionTypeBot(TDObject, tag="starSubscriptionTypeBot", kw_only=True):
    """Describes a subscription in a bot or a business account

    Attributes:
        is_canceled_by_bot: True, if the subscription was canceled by the bot and can't be
            extended
        title: Subscription invoice title
        photo: Subscription invoice photo
        invoice_link: The link to the subscription invoice
    """

    is_canceled_by_bot: bool = False
    title: str = ""
    photo: Photo
    invoice_link: str = ""


class StarSubscriptionPricing(TDObject, tag="starSubscriptionPricing", kw_only=True):
    """Describes subscription plan paid in Telegram Stars

    Attributes:
        period: The number of seconds between consecutive Telegram Star debiting
        star_count: The Telegram Star amount that must be paid for each period
    """

    period: int = 0
    star_count: int = 0


class StarSubscription(TDObject, tag="starSubscription", kw_only=True):
    """Contains information about subscription to a channel chat, a bot, or a business account
    that was paid in Telegram Stars

    Attributes:
        id: Unique identifier of the subscription
        chat_id: Identifier of the chat that is subscribed
        expiration_date: Point in time (Unix timestamp) when the subscription will expire or
            expired
        is_canceled: True, if the subscription was canceled
        is_expiring: True, if the subscription expires soon and there aren't enough Telegram
            Stars on the user's balance to extend it
        pricing: The subscription plan
        type: Type of the subscription
    """

    id: str = ""
    chat_id: int = 0
    expiration_date: int = 0
    is_canceled: bool = False
    is_expiring: bool = False
    pricing: StarSubscriptionPricing
    type: StarSubscriptionType


class StarSubscriptions(TDObject, tag="starSubscriptions", kw_only=True):
    """Represents a list of Telegram Star subscriptions

    Attributes:
        star_amount: The amount of owned Telegram Stars
        subscriptions: List of subscriptions for Telegram Stars
        required_star_count: The number of Telegram Stars required to buy to extend
            subscriptions expiring soon
        next_offset: The offset for the next request. If empty, then there are no more
            results
    """

    star_amount: StarAmount
    subscriptions: list[StarSubscription] = []
    required_star_count: int = 0
    next_offset: str = ""


