class Gift(TDObject, tag="gift", kw_only=True):
    """Describes a gift that can be sent to another user or channel chat

    Attributes:
        id: Unique identifier of the gift
        publisher_chat_id: Identifier of the chat that published the gift; 0 if none
        sticker: The sticker representing the gift
        star_count: Number of Telegram Stars that must be paid for the gift
        default_sell_star_count: Number of Telegram Stars that can be claimed by the
            receiver instead of the regular gift by default. If the gift was paid with just
            bought Telegram Stars, then full value can be claimed
        upgrade_star_count: Number of Telegram Stars that must be paid to upgrade the gift;
            0 if upgrade isn't possible
        upgrade_variant_count: Number of unique gift variants that are available for the
            upgraded gift; 0 if unknown
        has_colors: True, if the gift can be used to customize the user's name, and
            backgrounds of profile photo, reply header, and link preview
        is_for_birthday: True, if the gift is a birthday gift
        is_premium: True, if the gift can be bought only by Telegram Premium subscribers
        auction_info: Information about the auction on which the gift can be purchased; may
            be null if the gift can be purchased directly
        next_send_date: Point in time (Unix timestamp) when the gift can be sent next time
            by the current user; may be 0 or a date in the past. If the date is in the
            future, then call canSendGift to get the reason, why the gift can't be sent now
        user_limits: Number of times the gift can be purchased by the current user; may be
            null if not limited
        overall_limits: Number of times the gift can be purchased by all users; may be null
            if not limited
        background: Background of the gift
        first_send_date: Point in time (Unix timestamp) when the gift was sent for the first
            time; for sold out gifts only
        last_send_date: Point in time (Unix timestamp) when the gift was sent for the last
            time; for sold out gifts only
    """

    id: Int64 = Int64(0)
    publisher_chat_id: int = 0
    sticker: Sticker
    star_count: int = 0
    default_sell_star_count: int = 0
    upgrade_star_count: int = 0
    upgrade_variant_count: int = 0
    has_colors: bool = False
    is_for_birthday: bool = False
    is_premium: bool = False
    auction_info: GiftAuction | None = None
    next_send_date: int = 0
    user_limits: GiftPurchaseLimits | None = None
    overall_limits: GiftPurchaseLimits | None = None
    background: GiftBackground
    first_send_date: int = 0
    last_send_date: int = 0


class UpgradedGift(TDObject, tag="upgradedGift", kw_only=True):
    """Describes an upgraded gift that can be transferred to another owner or transferred to
    the TON blockchain as an NFT

    Attributes:
        id: Unique identifier of the gift
        regular_gift_id: Unique identifier of the regular gift from which the gift was
            upgraded; may be 0 for short period of time for old gifts from database
        publisher_chat_id: Identifier of the chat that published the gift; 0 if none
        title: The title of the upgraded gift
        name: Unique name of the upgraded gift that can be used with
            internalLinkTypeUpgradedGift or sendResoldGift
        number: Unique number of the upgraded gift among gifts upgraded from the same gift
        total_upgraded_count: Total number of gifts that were upgraded from the same gift
        max_upgraded_count: The maximum number of gifts that can be upgraded from the same
            gift
        is_burned: True, if the gift was used to craft another gift
        is_crafted: True, if the gift was crafted from other gifts
        is_premium: True, if the original gift could have been bought only by Telegram
            Premium subscribers
        is_theme_available: True, if the gift can be used to set a theme in a chat
        used_theme_chat_id: Identifier of the chat for which the gift is used to set a
            theme; 0 if none or the gift isn't owned by the current user
        host_id: Identifier of the user or the chat to which the upgraded gift was assigned
            from blockchain; may be null if none or unknown
        owner_id: Identifier of the user or the chat that owns the upgraded gift; may be
            null if none or unknown
        owner_address: Address of the gift NFT owner in TON blockchain; may be empty if
            none. Append the address to getOption("ton_blockchain_explorer_url") to get a
            link with information about the address
        owner_name: Name of the owner for the case when owner identifier and address aren't
            known
        gift_address: Address of the gift NFT in TON blockchain; may be empty if none.
            Append the address to getOption("ton_blockchain_explorer_url") to get a link
            with information about the address
        model: Model of the upgraded gift
        symbol: Symbol of the upgraded gift
        backdrop: Backdrop of the upgraded gift
        original_details: Information about the originally sent gift; may be null if unknown
        colors: Colors that can be set for user's name, background of empty chat photo,
            replies to messages and link previews; may be null if none or unknown
        resale_parameters: Resale parameters of the gift; may be null if resale isn't
            possible
        can_send_purchase_offer: True, if an offer to purchase the gift can be sent using
            sendGiftPurchaseOffer
        craft_probability_per_mille: Probability that the gift adds to the chance of
            successful crafting of a new gift; 0 if the gift can't be used for crafting
        value_currency: ISO 4217 currency code of the currency in which value of the gift is
            represented; may be empty if unavailable
        value_amount: Estimated value of the gift; in the smallest units of the currency; 0
            if unavailable
        value_usd_amount: Estimated value of the gift in USD; in USD cents; 0 if unavailable
    """

    id: Int64 = Int64(0)
    regular_gift_id: Int64 = Int64(0)
    publisher_chat_id: int = 0
    title: str = ""
    name: str = ""
    number: int = 0
    total_upgraded_count: int = 0
    max_upgraded_count: int = 0
    is_burned: bool = False
    is_crafted: bool = False
    is_premium: bool = False
    is_theme_available: bool = False
    used_theme_chat_id: int = 0
    host_id: MessageSender | None = None
    owner_id: MessageSender | None = None
    owner_address: str = ""
    owner_name: str = ""
    gift_address: str = ""
    model: UpgradedGiftModel
    symbol: UpgradedGiftSymbol
    backdrop: UpgradedGiftBackdrop
    original_details: UpgradedGiftOriginalDetails | None = None
    colors: UpgradedGiftColors | None = None
    resale_parameters: GiftResaleParameters | None = None
    can_send_purchase_offer: bool = False
    craft_probability_per_mille: int = 0
    value_currency: str = ""
    value_amount: int = 0
    value_usd_amount: int = 0


class UpgradedGiftValueInfo(TDObject, tag="upgradedGiftValueInfo", kw_only=True):
    """Contains information about value of an upgraded gift

    Attributes:
        currency: ISO 4217 currency code of the currency in which the prices are represented
        value: Estimated value of the gift; in the smallest units of the currency
        is_value_average: True, if the value is calculated as average value of similar sold
            gifts. Otherwise, it is based on the sale price of the gift
        initial_sale_date: Point in time (Unix timestamp) when the corresponding regular
            gift was originally purchased
        initial_sale_star_count: The Telegram Star amount that was paid for the gift
        initial_sale_price: Initial price of the gift; in the smallest units of the currency
        last_sale_date: Point in time (Unix timestamp) when the upgraded gift was purchased
            last time; 0 if never
        last_sale_price: Last purchase price of the gift; in the smallest units of the
            currency; 0 if the gift has never been resold
        is_last_sale_on_fragment: True, if the last sale was completed on Fragment
        minimum_price: The current minimum price of gifts upgraded from the same gift; in
            the smallest units of the currency; 0 if there are no such gifts
        average_sale_price: The average sale price in the last month of gifts upgraded from
            the same gift; in the smallest units of the currency; 0 if there were no such
            sales
        telegram_listed_gift_count: Number of gifts upgraded from the same gift being resold
            on Telegram
        fragment_listed_gift_count: Number of gifts upgraded from the same gift being resold
            on Fragment
        fragment_url: The HTTPS link to the Fragment for the gift; may be empty if there are
            no such gifts being sold on Fragment
    """

    currency: str = ""
    value: int = 0
    is_value_average: bool = False
    initial_sale_date: int = 0
    initial_sale_star_count: int = 0
    initial_sale_price: int = 0
    last_sale_date: int = 0
    last_sale_price: int = 0
    is_last_sale_on_fragment: bool = False
    minimum_price: int = 0
    average_sale_price: int = 0
    telegram_listed_gift_count: int = 0
    fragment_listed_gift_count: int = 0
    fragment_url: str = ""


class UpgradeGiftResult(TDObject, tag="upgradeGiftResult", kw_only=True):
    """Contains result of gift upgrading

    Attributes:
        gift: The upgraded gift
        received_gift_id: Unique identifier of the received gift for the current user
        is_saved: True, if the gift is displayed on the user's or the channel's profile page
        can_be_transferred: True, if the gift can be transferred to another owner
        transfer_star_count: Number of Telegram Stars that must be paid to transfer the
            upgraded gift
        drop_original_details_star_count: Number of Telegram Stars that must be paid to drop
            original details of the upgraded gift; 0 if not available
        next_transfer_date: Point in time (Unix timestamp) when the gift can be transferred
            to another owner; can be in the past; 0 if the gift can be transferred
            immediately or transfer isn't possible
        next_resale_date: Point in time (Unix timestamp) when the gift can be resold to
            another user; can be in the past; 0 if the gift can't be resold; only for the
            receiver of the gift
        export_date: Point in time (Unix timestamp) when the gift can be transferred to the
            TON blockchain as an NFT; can be in the past
    """

    gift: UpgradedGift
    received_gift_id: str = ""
    is_saved: bool = False
    can_be_transferred: bool = False
    transfer_star_count: int = 0
    drop_original_details_star_count: int = 0
    next_transfer_date: int = 0
    next_resale_date: int = 0
    export_date: int = 0


