class Usernames(TDObject, tag="usernames", kw_only=True):
    """Describes usernames assigned to a user, a supergroup, or a channel

    Attributes:
        active_usernames: List of active usernames; the first one must be shown as the
            primary username. The order of active usernames can be changed with
            reorderActiveUsernames, reorderBotActiveUsernames or
            reorderSupergroupActiveUsernames
        disabled_usernames: List of currently disabled usernames; the username can be
            activated with toggleUsernameIsActive, toggleBotUsernameIsActive, or
            toggleSupergroupUsernameIsActive
        editable_username: Active or disabled username, which may be changed with
            setUsername or setSupergroupUsername
        collectible_usernames: Collectible usernames that were purchased at
            https://fragment.com and can be passed to getCollectibleItemInfo for more
            details
    """

    active_usernames: list[str] = []
    disabled_usernames: list[str] = []
    editable_username: str = ""
    collectible_usernames: list[str] = []


class User(TDObject, tag="user", kw_only=True):
    """Represents a user

    Attributes:
        id: User identifier
        first_name: First name of the user
        last_name: Last name of the user
        usernames: Usernames of the user; may be null
        phone_number: Phone number of the user
        status: Current online status of the user
        profile_photo: Profile photo of the user; may be null
        accent_color_id: Identifier of the accent color for name, and backgrounds of profile
            photo, reply header, and link preview
        background_custom_emoji_id: Identifier of a custom emoji to be shown on the reply
            header and link preview background; 0 if none
        upgraded_gift_colors: Color scheme based on an upgraded gift to be used for the user
            instead of accent_color_id and background_custom_emoji_id; may be null if none
        profile_accent_color_id: Identifier of the accent color for the user's profile; -1
            if none
        profile_background_custom_emoji_id: Identifier of a custom emoji to be shown on the
            background of the user's profile; 0 if none
        emoji_status: Emoji status to be shown instead of the default Telegram Premium
            badge; may be null
        is_contact: The user is a contact of the current user
        is_mutual_contact: The user is a contact of the current user and the current user is
            a contact of the user
        is_close_friend: The user is a close friend of the current user; implies that the
            user is a contact
        verification_status: Information about verification status of the user; may be null
            if none
        is_premium: True, if the user is a Telegram Premium user
        is_support: True, if the user is Telegram support account
        restriction_info: Information about restrictions that must be applied to the
            corresponding private chat; may be null if none
        active_story_state: State of active stories of the user; may be null if the user has
            no active stories
        restricts_new_chats: True, if the user may restrict new chats with non-contacts. Use
            canSendMessageToUser to check whether the current user can message the user or
            try to create a chat with them
        paid_message_star_count: Number of Telegram Stars that must be paid by general user
            for each sent message to the user. If positive and userFullInfo is unknown, use
            canSendMessageToUser to check whether the current user must pay
        have_access: If false, the user is inaccessible, and the only information known
            about the user is inside this class. Identifier of the user can't be passed to
            any method
        type: Type of the user
        language_code: IETF language tag of the user's language; only available to bots
        added_to_attachment_menu: True, if the user added the current bot to attachment
            menu; only available to bots
    """

    id: int = 0
    first_name: str = ""
    last_name: str = ""
    usernames: Usernames | None = None
    phone_number: str = ""
    status: UserStatus
    profile_photo: ProfilePhoto | None = None
    accent_color_id: int = 0
    background_custom_emoji_id: Int64 = Int64(0)
    upgraded_gift_colors: UpgradedGiftColors | None = None
    profile_accent_color_id: int = 0
    profile_background_custom_emoji_id: Int64 = Int64(0)
    emoji_status: EmojiStatus | None = None
    is_contact: bool = False
    is_mutual_contact: bool = False
    is_close_friend: bool = False
    verification_status: VerificationStatus | None = None
    is_premium: bool = False
    is_support: bool = False
    restriction_info: RestrictionInfo | None = None
    active_story_state: ActiveStoryState | None = None
    restricts_new_chats: bool = False
    paid_message_star_count: int = 0
    have_access: bool = False
    type: UserType
    language_code: str = ""
    added_to_attachment_menu: bool = False


class BotInfo(TDObject, tag="botInfo", kw_only=True):
    """Contains information about a bot

    Attributes:
        short_description: The text that is shown on the bot's profile page and is sent
            together with the link when users share the bot @param_description The text
            shown in the chat with the bot if the chat is empty
        description: Undocumented in the TL schema.
        photo: Photo shown in the chat with the bot if the chat is empty; may be null
        animation: Animation shown in the chat with the bot if the chat is empty; may be
            null
        manager_bot_user_id: Identifier of the bot, which manages the bot; 0 if none or
            unknown; for owner of the bot only
        menu_button: Information about a button to show instead of the bot commands menu
            button; may be null if ordinary bot commands menu must be shown
        commands: List of the bot commands
        privacy_policy_url: The HTTP link to the privacy policy of the bot. If empty, then
            /privacy command must be used if supported by the bot. If the command isn't
            supported, then https://telegram.org/privacy-tpa must be opened
        default_group_administrator_rights: Default administrator rights for adding the bot
            to basic group and supergroup chats; may be null
        default_channel_administrator_rights: Default administrator rights for adding the
            bot to channels; may be null
        affiliate_program: Information about the affiliate program of the bot; may be null
            if none
        web_app_background_light_color: Default light background color for bot Web Apps; -1
            if not specified
        web_app_background_dark_color: Default dark background color for bot Web Apps; -1 if
            not specified
        web_app_header_light_color: Default light header color for bot Web Apps; -1 if not
            specified
        web_app_header_dark_color: Default dark header color for bot Web Apps; -1 if not
            specified
        verification_parameters: Parameters of the verification that can be provided by the
            bot; may be null if none or the current user isn't the owner of the bot
        can_get_revenue_statistics: True, if the bot's revenue statistics are available to
            the current user
        can_manage_emoji_status: True, if the bot can manage emoji status of the current
            user
        has_media_previews: True, if the bot has media previews
        edit_commands_link: The internal link, which can be used to edit bot commands; may
            be null
        edit_description_link: The internal link, which can be used to edit bot description;
            may be null
        edit_description_media_link: The internal link, which can be used to edit the photo
            or animation shown in the chat with the bot if the chat is empty; may be null
        edit_settings_link: The internal link, which can be used to edit bot settings; may
            be null
    """

    short_description: str = ""
    description: str = ""
    photo: Photo | None = None
    animation: Animation | None = None
    manager_bot_user_id: int = 0
    menu_button: BotMenuButton | None = None
    commands: list[BotCommand] = []
    privacy_policy_url: str = ""
    default_group_administrator_rights: ChatAdministratorRights | None = None
    default_channel_administrator_rights: ChatAdministratorRights | None = None
    affiliate_program: AffiliateProgramInfo | None = None
    web_app_background_light_color: int = 0
    web_app_background_dark_color: int = 0
    web_app_header_light_color: int = 0
    web_app_header_dark_color: int = 0
    verification_parameters: BotVerificationParameters | None = None
    can_get_revenue_statistics: bool = False
    can_manage_emoji_status: bool = False
    has_media_previews: bool = False
    edit_commands_link: InternalLinkType | None = None
    edit_description_link: InternalLinkType | None = None
    edit_description_media_link: InternalLinkType | None = None
    edit_settings_link: InternalLinkType | None = None


class UserFullInfo(TDObject, tag="userFullInfo", kw_only=True):
    """Contains full information about a user

    Attributes:
        personal_photo: User profile photo set by the current user for the contact; may be
            null. If null and user.profile_photo is null, then the photo is empty;
            otherwise, it is unknown. If non-null, then it is the same photo as in
            user.profile_photo and chat.photo. This photo isn't returned in the list of user
            photos
        photo: User profile photo; may be null. If null and user.profile_photo is null, then
            the photo is empty; otherwise, it is unknown. If non-null and personal_photo is
            null, then it is the same photo as in user.profile_photo and chat.photo
        public_photo: User profile photo visible if the main photo is hidden by privacy
            settings; may be null. If null and user.profile_photo is null, then the photo is
            empty; otherwise, it is unknown. If non-null and both photo and personal_photo
            are null, then it is the same photo as in user.profile_photo and chat.photo.
            This photo isn't returned in the list of user photos
        community_id: Identifier of the community to which chat with the bot was added; for
            bots only
        block_list: Block list to which the user is added; may be null if none
        can_be_called: True, if the user can be called
        supports_video_calls: True, if a video call can be created with the user
        has_private_calls: True, if the user can't be called due to their privacy settings
        has_private_forwards: True, if the user can't be linked in forwarded messages due to
            their privacy settings
        has_restricted_voice_and_video_note_messages: True, if voice and video notes can't
            be sent or forwarded to the user
        has_posted_to_profile_stories: True, if the user has posted to profile stories
        has_sponsored_messages_enabled: True, if the user always enabled sponsored messages;
            known only for the current user
        need_phone_number_privacy_exception: True, if the current user needs to explicitly
            allow to share their phone number with the user when the method addContact is
            used
        set_chat_background: True, if the user set chat background for both chat users and
            it wasn't reverted yet
        uses_unofficial_app: True, if the user uses an unofficial application that poses a
            security risk
        bio: A short user bio; may be null for bots
        birthdate: Birthdate of the user; may be null if unknown
        personal_chat_id: Identifier of the personal chat of the user; 0 if none
        gift_count: Number of saved to profile gifts for other users or the total number of
            received gifts for the current user
        group_in_common_count: Number of group chats where both the other user and the
            current user are a member; 0 for the current user
        incoming_paid_message_star_count: Number of Telegram Stars that must be paid by the
            user for each sent message to the current user
        outgoing_paid_message_star_count: Number of Telegram Stars that must be paid by the
            current user for each sent message to the user
        gift_settings: Settings for gift receiving for the user
        bot_verification: Information about verification status of the user provided by a
            bot; may be null if none or unknown
        main_profile_tab: The main tab chosen by the user; may be null if not chosen
            manually
        first_profile_audio: The first audio file added to the user's profile; may be null
            if none
        rating: The current rating of the user; may be null if none
        pending_rating: The rating of the user after the next change; may be null if the
            user isn't the current user or there are no pending rating changes
        pending_rating_date: Unix timestamp when rating of the user will change to
            pending_rating; 0 if the user isn't the current user or there are no pending
            rating changes
        note: Note added to the user's contact; may be null if none
        business_info: Information about business settings for Telegram Business accounts;
            may be null if none
        bot_info: For bots, information about the bot; may be null if the user isn't a bot
    """

    personal_photo: ChatPhoto | None = None
    photo: ChatPhoto | None = None
    public_photo: ChatPhoto | None = None
    community_id: int = 0
    block_list: BlockList | None = None
    can_be_called: bool = False
    supports_video_calls: bool = False
    has_private_calls: bool = False
    has_private_forwards: bool = False
    has_restricted_voice_and_video_note_messages: bool = False
    has_posted_to_profile_stories: bool = False
    has_sponsored_messages_enabled: bool = False
    need_phone_number_privacy_exception: bool = False
    set_chat_background: bool = False
    uses_unofficial_app: bool = False
    bio: FormattedText | None = None
    birthdate: Birthdate | None = None
    personal_chat_id: int = 0
    gift_count: int = 0
    group_in_common_count: int = 0
    incoming_paid_message_star_count: int = 0
    outgoing_paid_message_star_count: int = 0
    gift_settings: GiftSettings
    bot_verification: BotVerification | None = None
    main_profile_tab: ProfileTab | None = None
    first_profile_audio: Audio | None = None
    rating: UserRating | None = None
    pending_rating: UserRating | None = None
    pending_rating_date: int = 0
    note: FormattedText | None = None
    business_info: BusinessInfo | None = None
    bot_info: BotInfo | None = None


