class Supergroup(TDObject, tag="supergroup", kw_only=True):
    """Represents a supergroup or channel with zero or more members (subscribers in the case of
    channels)

    Attributes:
        id: Supergroup or channel identifier
        usernames: Usernames of the supergroup or channel; may be null
        date: Point in time (Unix timestamp) when the current user joined, or the point in
            time when the supergroup or channel was created, in case the user is not a
            member
        status: Status of the current user in the supergroup or channel
        member_count: Number of members in the supergroup or channel; 0 if unknown.
            Currently, it is guaranteed to be known only if the supergroup or channel was
            received through getChatSimilarChats, getChatsToPostStories,
            getCreatedPublicChats, getGroupsInCommon, getInactiveSupergroupChats,
            getRecommendedChats, getSuitableDiscussionChats, getUserPrivacySettingRules,
            getVideoChatAvailableParticipants, searchPublicChats, or in
            chatFolderInviteLinkInfo.missing_chat_ids, or in userFullInfo.personal_chat_id,
            or for chats with messages or stories from publicForwards and foundStories
        boost_level: Approximate boost level for the chat
        has_automatic_translation: True, if automatic translation of messages is enabled in
            the channel
        has_linked_chat: True, if the channel has a discussion group, or the supergroup is
            the designated discussion group for a channel
        has_location: True, if the supergroup is connected to a location, i.e. the
            supergroup is a location-based supergroup
        sign_messages: True, if messages sent to the channel contains name of the sender.
            This field is only applicable to channels
        show_message_sender: True, if messages sent to the channel have information about
            the sender user. This field is only applicable to channels
        join_to_send_messages: True, if users need to join the supergroup before they can
            send messages. May be false only for discussion supergroups and channel direct
            messages groups
        join_by_request: True, if all users directly joining the supergroup need to be
            approved by supergroup administrators
        is_slow_mode_enabled: True, if the slow mode is enabled in the supergroup
        is_channel: True, if the supergroup is a channel, which can have an unlimited number
            of subscribers, but only administrators can post there and see the list of
            subscribers
        is_broadcast_group: True, if the supergroup is a broadcast group, i.e. only
            administrators can send messages and there is no limit on the number of members
        is_forum: True, if the supergroup is a forum with topics
        is_direct_messages_group: True, if the supergroup is a direct message group for a
            channel chat
        is_administered_direct_messages_group: True, if the supergroup is a direct messages
            group for a channel chat that is administered by the current user
        verification_status: Information about verification status of the supergroup or
            channel; may be null if none
        has_direct_messages_group: True, if the channel has direct messages group
        has_forum_tabs: True, if the supergroup is a forum, which topics are shown in the
            same way as in channel direct messages groups
        restriction_info: Information about the restrictions that must be applied to the
            corresponding supergroup or channel chat; may be null if none
        paid_message_star_count: Number of Telegram Stars that must be paid by
            non-administrator users of the supergroup chat for each sent message
        active_story_state: State of active stories of the supergroup or channel; may be
            null if there are no active stories
    """

    id: int = 0
    usernames: Usernames | None = None
    date: int = 0
    status: ChatMemberStatus
    member_count: int = 0
    boost_level: int = 0
    has_automatic_translation: bool = False
    has_linked_chat: bool = False
    has_location: bool = False
    sign_messages: bool = False
    show_message_sender: bool = False
    join_to_send_messages: bool = False
    join_by_request: bool = False
    is_slow_mode_enabled: bool = False
    is_channel: bool = False
    is_broadcast_group: bool = False
    is_forum: bool = False
    is_direct_messages_group: bool = False
    is_administered_direct_messages_group: bool = False
    verification_status: VerificationStatus | None = None
    has_direct_messages_group: bool = False
    has_forum_tabs: bool = False
    restriction_info: RestrictionInfo | None = None
    paid_message_star_count: int = 0
    active_story_state: ActiveStoryState | None = None


class SupergroupFullInfo(TDObject, tag="supergroupFullInfo", kw_only=True):
    """Contains full information about a supergroup or channel

    Attributes:
        photo: Chat photo; may be null if empty or unknown. If non-null, then it is the same
            photo as in chat.photo
        community_id: Identifier of the community to which the corresponding chat was added
            @param_description Supergroup or channel description
        description: Undocumented in the TL schema.
        member_count: Number of members in the supergroup or channel; 0 if unknown
        administrator_count: Number of privileged users in the supergroup or channel; 0 if
            unknown
        restricted_count: Number of restricted users in the supergroup; 0 if unknown
        banned_count: Number of users banned from chat; 0 if unknown
        linked_chat_id: Chat identifier of a discussion group for the channel, or a channel,
            for which the supergroup is the designated discussion group; 0 if none or
            unknown
        direct_messages_chat_id: Chat identifier of a direct messages group for the channel,
            or a channel, for which the supergroup is the designated direct messages group;
            0 if none
        slow_mode_delay: Delay between consecutive sent messages for non-administrator
            supergroup members, in seconds
        slow_mode_delay_expires_in: Time left before next message can be sent in the
            supergroup, in seconds. An updateSupergroupFullInfo update is not triggered when
            value of this field changes, but both new and old values are non-zero
        can_enable_paid_messages: True, if paid messages can be enabled in the supergroup
            chat; for supergroup only
        can_enable_paid_reaction: True, if paid reaction can be enabled in the channel chat;
            for channels only
        can_get_members: True, if members of the chat can be retrieved via
            getSupergroupMembers or searchChatMembers
        has_hidden_members: True, if non-administrators can receive only administrators and
            bots using getSupergroupMembers or searchChatMembers
        can_hide_members: True, if non-administrators and non-bots can be hidden in
            responses to getSupergroupMembers and searchChatMembers for non-administrators
        can_set_sticker_set: True, if the supergroup sticker set can be changed
        can_set_location: True, if the supergroup location can be changed
        can_get_statistics: True, if the supergroup or channel statistics are available
        can_get_revenue_statistics: True, if the supergroup or channel revenue statistics
            are available
        can_get_star_revenue_statistics: True, if the supergroup or channel Telegram Star
            revenue statistics are available
        can_send_gift: True, if the user can send a gift to the supergroup or channel using
            sendGift or transferGift
        can_toggle_aggressive_anti_spam: True, if aggressive anti-spam checks can be enabled
            or disabled in the supergroup
        is_all_history_available: True, if new chat members will have access to old
            messages. In public, discussion, of forum groups and all channels, old messages
            are always available, so this option affects only private non-forum supergroups
            without a linked chat. The value of this field is only available to chat
            administrators
        can_have_sponsored_messages: True, if the chat can have sponsored messages. The
            value of this field is only available to the owner of the chat
        has_aggressive_anti_spam_enabled: True, if aggressive anti-spam checks are enabled
            in the supergroup. The value of this field is only available to chat
            administrators
        has_paid_media_allowed: True, if paid media can be sent and forwarded to the channel
            chat; for channels only
        has_pinned_stories: True, if the supergroup or channel has pinned stories
        gift_count: Number of saved to profile gifts for channels without can_post_messages
            administrator right, otherwise, the total number of received gifts
        my_boost_count: Number of times the current user boosted the supergroup or channel
        unrestrict_boost_count: Number of times the supergroup must be boosted by a user to
            ignore slow mode and chat permission restrictions; 0 if unspecified
        outgoing_paid_message_star_count: Number of Telegram Stars that must be paid by the
            current user for each sent message to the supergroup
        sticker_set_id: Identifier of the supergroup sticker set that must be shown before
            user sticker sets; 0 if none
        custom_emoji_sticker_set_id: Identifier of the custom emoji sticker set that can be
            used in the supergroup without Telegram Premium subscription; 0 if none
        location: Location to which the supergroup is connected; may be null if none
        invite_link: Primary invite link for the chat; may be null. For chat administrators
            with can_invite_users right only
        guard_bot_user_id: User identifier of the guard bot in the group; for chat
            administrators only
        bot_commands: List of commands of bots in the group
        bot_verification: Information about verification status of the supergroup or the
            channel provided by a bot; may be null if none or unknown
        main_profile_tab: The main tab chosen by the administrators of the channel; may be
            null if not chosen manually
        upgraded_from_basic_group_id: Identifier of the basic group from which supergroup
            was upgraded; 0 if none
        upgraded_from_max_message_id: Identifier of the last message in the basic group from
            which supergroup was upgraded; 0 if none
    """

    photo: ChatPhoto | None = None
    community_id: int = 0
    description: str = ""
    member_count: int = 0
    administrator_count: int = 0
    restricted_count: int = 0
    banned_count: int = 0
    linked_chat_id: int = 0
    direct_messages_chat_id: int = 0
    slow_mode_delay: int = 0
    slow_mode_delay_expires_in: float = 0.0
    can_enable_paid_messages: bool = False
    can_enable_paid_reaction: bool = False
    can_get_members: bool = False
    has_hidden_members: bool = False
    can_hide_members: bool = False
    can_set_sticker_set: bool = False
    can_set_location: bool = False
    can_get_statistics: bool = False
    can_get_revenue_statistics: bool = False
    can_get_star_revenue_statistics: bool = False
    can_send_gift: bool = False
    can_toggle_aggressive_anti_spam: bool = False
    is_all_history_available: bool = False
    can_have_sponsored_messages: bool = False
    has_aggressive_anti_spam_enabled: bool = False
    has_paid_media_allowed: bool = False
    has_pinned_stories: bool = False
    gift_count: int = 0
    my_boost_count: int = 0
    unrestrict_boost_count: int = 0
    outgoing_paid_message_star_count: int = 0
    sticker_set_id: Int64 = Int64(0)
    custom_emoji_sticker_set_id: Int64 = Int64(0)
    location: ChatLocation | None = None
    invite_link: ChatInviteLink | None = None
    guard_bot_user_id: int = 0
    bot_commands: list[BotCommands] = []
    bot_verification: BotVerification | None = None
    main_profile_tab: ProfileTab | None = None
    upgraded_from_basic_group_id: int = 0
    upgraded_from_max_message_id: int = 0


class SecretChatStatePending(TDObject, tag="secretChatStatePending", kw_only=True):
    """The secret chat is not yet created; waiting for the other user to get online"""


class SecretChatStateReady(TDObject, tag="secretChatStateReady", kw_only=True):
    """The secret chat is ready to use"""


class SecretChatStateClosed(TDObject, tag="secretChatStateClosed", kw_only=True):
    """The secret chat is closed"""


class SecretChat(TDObject, tag="secretChat", kw_only=True):
    """Represents a secret chat

    Attributes:
        id: Secret chat identifier
        user_id: Identifier of the chat partner
        state: State of the secret chat
        is_outbound: True, if the chat was created by the current user; false otherwise
        key_hash: Hash of the currently used key for comparison with the hash of the chat
            partner's key. This is a string of 36 little-endian bytes, which must be split
            into groups of 2 bits, each denoting a pixel of one of 4 colors FFFFFF, D5E6F3,
            2D5775, and 2F99C9. The pixels must be used to make a 12x12 square image filled
            from left to right, top to bottom. Alternatively, the first 32 bytes of the hash
            can be converted to the hexadecimal format and printed as 32 2-digit hex numbers
        layer: Secret chat layer; determines features supported by the chat partner's
            application. Nested text entities and underline and strikethrough entities are
            supported if the layer >= 101, files bigger than 2000MB are supported if the
            layer >= 143, spoiler and custom emoji text entities are supported if the layer
            >= 144
    """

    id: int = 0
    user_id: int = 0
    state: SecretChatState
    is_outbound: bool = False
    key_hash: bytes = b""
    layer: int = 0


