class ChatNotificationSettings(TDObject, tag="chatNotificationSettings", kw_only=True):
    """Contains information about notification settings for a chat or a forum topic

    Attributes:
        use_default_mute_for: If true, the value for the relevant type of chat or the forum
            chat is used instead of mute_for
        mute_for: Time left before notifications will be unmuted, in seconds
        use_default_sound: If true, the value for the relevant type of chat or the forum
            chat is used instead of sound_id
        sound_id: Identifier of the notification sound to be played for messages; 0 if sound
            is disabled
        use_default_show_preview: If true, the value for the relevant type of chat or the
            forum chat is used instead of show_preview
        show_preview: True, if message content must be displayed in notifications
        use_default_mute_stories: If true, the value for the relevant type of chat is used
            instead of mute_stories
        mute_stories: True, if story notifications are disabled for the chat
        use_default_story_sound: If true, the value for the relevant type of chat is used
            instead of story_sound_id
        story_sound_id: Identifier of the notification sound to be played for stories; 0 if
            sound is disabled
        use_default_show_story_poster: If true, the value for the relevant type of chat is
            used instead of show_story_poster
        show_story_poster: True, if the chat that posted a story must be displayed in
            notifications
        use_default_disable_pinned_message_notifications: If true, the value for the
            relevant type of chat or the forum chat is used instead of
            disable_pinned_message_notifications
        disable_pinned_message_notifications: If true, notifications for incoming pinned
            messages will be created as for an ordinary unread message
        use_default_disable_mention_notifications: If true, the value for the relevant type
            of chat or the forum chat is used instead of disable_mention_notifications
        disable_mention_notifications: If true, notifications for messages with mentions
            will be created as for an ordinary unread message
    """

    use_default_mute_for: bool = False
    mute_for: int = 0
    use_default_sound: bool = False
    sound_id: Int64 = Int64(0)
    use_default_show_preview: bool = False
    show_preview: bool = False
    use_default_mute_stories: bool = False
    mute_stories: bool = False
    use_default_story_sound: bool = False
    story_sound_id: Int64 = Int64(0)
    use_default_show_story_poster: bool = False
    show_story_poster: bool = False
    use_default_disable_pinned_message_notifications: bool = False
    disable_pinned_message_notifications: bool = False
    use_default_disable_mention_notifications: bool = False
    disable_mention_notifications: bool = False


class ScopeNotificationSettings(TDObject, tag="scopeNotificationSettings", kw_only=True):
    """Contains information about notification settings for several chats

    Attributes:
        mute_for: Time left before notifications will be unmuted, in seconds
        sound_id: Identifier of the notification sound to be played; 0 if sound is disabled;
            pass -1 to use the app-dependent default sound
        show_preview: True, if message content must be displayed in notifications
        use_default_mute_stories: If true, story notifications are received only for the
            first 5 chats from topChatCategoryUsers regardless of the value of mute_stories
        mute_stories: True, if story notifications are disabled
        story_sound_id: Identifier of the notification sound to be played for stories; 0 if
            sound is disabled; pass -1 to use the app-dependent default sound
        show_story_poster: True, if the chat that posted a story must be displayed in
            notifications
        disable_pinned_message_notifications: True, if notifications for incoming pinned
            messages will be created as for an ordinary unread message
        disable_mention_notifications: True, if notifications for messages with mentions
            will be created as for an ordinary unread message
    """

    mute_for: int = 0
    sound_id: Int64 = Int64(0)
    show_preview: bool = False
    use_default_mute_stories: bool = False
    mute_stories: bool = False
    story_sound_id: Int64 = Int64(0)
    show_story_poster: bool = False
    disable_pinned_message_notifications: bool = False
    disable_mention_notifications: bool = False


