class Invoice(TDObject, tag="invoice", kw_only=True):
    """Product invoice

    Attributes:
        currency: ISO 4217 currency code
        price_parts: A list of objects used to calculate the total price of the product
        subscription_period: The number of seconds between consecutive Telegram Star
            debiting for subscription invoices; 0 if the invoice doesn't create subscription
        max_tip_amount: The maximum allowed amount of tip in the smallest units of the
            currency
        suggested_tip_amounts: Suggested amounts of tip in the smallest units of the
            currency
        recurring_payment_terms_of_service_url: An HTTP URL with terms of service for
            recurring payments. If non-empty, the invoice payment will result in recurring
            payments and the user must accept the terms of service before allowed to pay
        terms_of_service_url: An HTTP URL with terms of service for non-recurring payments.
            If non-empty, then the user must accept the terms of service before allowed to
            pay
        is_test: True, if the payment is a test payment
        need_name: True, if the user's name is needed for payment
        need_phone_number: True, if the user's phone number is needed for payment
        need_email_address: True, if the user's email address is needed for payment
        need_shipping_address: True, if the user's shipping address is needed for payment
        send_phone_number_to_provider: True, if the user's phone number will be sent to the
            provider
        send_email_address_to_provider: True, if the user's email address will be sent to
            the provider
        is_flexible: True, if the total price depends on the shipping method
    """

    currency: str = ""
    price_parts: list[LabeledPricePart] = []
    subscription_period: int = 0
    max_tip_amount: int = 0
    suggested_tip_amounts: list[int] = []
    recurring_payment_terms_of_service_url: str = ""
    terms_of_service_url: str = ""
    is_test: bool = False
    need_name: bool = False
    need_phone_number: bool = False
    need_email_address: bool = False
    need_shipping_address: bool = False
    send_phone_number_to_provider: bool = False
    send_email_address_to_provider: bool = False
    is_flexible: bool = False


