class LanguagePackInfo(TDObject, tag="languagePackInfo", kw_only=True):
    """Contains information about a language pack

    Attributes:
        id: Unique language pack identifier
        base_language_pack_id: Identifier of a base language pack; may be empty. If a string
            is missed in the language pack, then it must be fetched from base language pack.
            Unsupported in custom language packs
        name: Language name
        native_name: Name of the language in that language
        plural_code: A language code to be used to apply plural forms. See
            https://www.unicode.org/cldr/charts/latest/supplemental/language_plural_rules.html
            for more information
        is_official: True, if the language pack is official
        is_rtl: True, if the language pack strings are RTL
        is_beta: True, if the language pack is a beta language pack
        is_installed: True, if the language pack is installed by the current user
        total_string_count: Total number of non-deleted strings from the language pack
        translated_string_count: Total number of translated strings from the language pack
        local_string_count: Total number of non-deleted strings from the language pack
            available locally
        translation_url: Link to language translation interface; empty for custom local
            language packs
    """

    id: str = ""
    base_language_pack_id: str = ""
    name: str = ""
    native_name: str = ""
    plural_code: str = ""
    is_official: bool = False
    is_rtl: bool = False
    is_beta: bool = False
    is_installed: bool = False
    total_string_count: int = 0
    translated_string_count: int = 0
    local_string_count: int = 0
    translation_url: str = ""


